// Core tests: the 21 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. The extra expected rolls below were derived with an independent
// integer-arithmetic re-implementation of the pinned mulberry32 (see
// AUTHOR-CHECK.md: the seed-42 numerator sequence
// [2581720956, 1925393290, 3661312704, 2876485805, 750819978] is
// cross-checked here as well).

import assert from "node:assert/strict";
import test from "node:test";
import { createPrng, run } from "../public/js/core/dice-roller.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("PRNG pin: seed 42 numerators match the AUTHOR-CHECK sequence", () => {
  const next = createPrng(42);
  assert.deepEqual(
    [next(), next(), next(), next(), next()],
    [2581720956, 1925393290, 3661312704, 2876485805, 750819978],
  );
});

test("worked anchors: 007d6 seed 42, 1d2 seed 0, 1d1000 max seed, 5d20 seed 12345", () => {
  assert.deepEqual(run({ notation: "007d6", seed: "42" }).result, {
    expression: "7d6",
    count: 7,
    sides: 6,
    modifier: 0,
    seed: 42,
    rolls: [4, 3, 6, 5, 2, 4, 2],
    sum: 26,
    total: 26,
  });
  assert.deepEqual(run({ notation: "1d2", seed: "0" }).result.rolls, [1]);
  assert.deepEqual(run({ notation: "1d1000", seed: "4294967295" }).result.rolls, [897]);
  assert.deepEqual(run({ notation: "1d2", seed: "4294967295" }).result.rolls, [2]);
  assert.deepEqual(run({ notation: "5d20", seed: "12345" }).result, {
    expression: "5d20",
    count: 5,
    sides: 20,
    modifier: 0,
    seed: 12345,
    rolls: [20, 7, 10, 17, 11],
    sum: 65,
    total: 65,
  });
});

test("equivalence: d20 and 1d20 roll identically; +0 and -0 normalize away", () => {
  const implicit = run({ notation: "d20", seed: "7" });
  const explicit = run({ notation: "1d20", seed: "7" });
  assert.deepEqual(implicit.result.rolls, explicit.result.rolls);
  assert.equal(implicit.result.expression, "1d20");
  assert.equal(run({ notation: "2d6+0", seed: "42" }).result.expression, "2d6");
  assert.equal(run({ notation: "2d6-0", seed: "42" }).result.expression, "2d6");
  assert.equal(run({ notation: "2d6+0", seed: "42" }).result.modifier, 0);
});

test("boundaries: 1d2, 100d2, and modifier -10000 at the caps", () => {
  const min = run({ notation: "1d2", seed: "0" });
  assert.equal(min.ok, true);
  assert.equal(min.result.rolls[0] >= 1 && min.result.rolls[0] <= 2, true);
  const hundred = run({ notation: "100d2", seed: "1" });
  assert.equal(hundred.ok, true);
  assert.equal(hundred.result.rolls.length, 100);
  assert.deepEqual(hundred.result.rolls.slice(0, 10), [2, 1, 2, 2, 2, 1, 2, 2, 1, 2]);
  assert.equal(hundred.result.sum, 147);
  const neg = run({ notation: "1d20-10000", seed: "7" });
  assert.equal(neg.ok, true);
  assert.equal(neg.result.total, -9999);
});

test("determinism and roll invariants: same snapshot, same rolls; rolls in 1..M", () => {
  const input = { notation: "5d20", seed: "12345" };
  assert.deepEqual(run(input), run(input));
  const outcome = run({ notation: "100d1000", seed: "99" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.rolls.length, 100);
  assert.equal(outcome.result.rolls.every((roll) => roll >= 1 && roll <= 1000), true);
  assert.equal(
    outcome.result.sum,
    outcome.result.rolls.reduce((total, roll) => total + roll, 0),
  );
  assert.equal(outcome.result.total, outcome.result.sum + outcome.result.modifier);
});

test("notation grammar: missing d, missing sides, trailing sign, trailing junk", () => {
  assert.deepEqual(errorOf({ notation: "d", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 1,
  });
  assert.deepEqual(errorOf({ notation: "2d6+", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 4,
  });
  assert.deepEqual(errorOf({ notation: "2d6+3x", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 5,
  });
  assert.deepEqual(errorOf({ notation: "2", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 1,
  });
});

test("notation grammar: no trimming, full-width digits are errors at first position", () => {
  assert.deepEqual(errorOf({ notation: " 2d6", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 0,
  });
  assert.deepEqual(errorOf({ notation: "2d6 ", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 3,
  });
  assert.deepEqual(errorOf({ notation: "２d6", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 0,
  });
  assert.deepEqual(errorOf({ notation: "2d6+ 3", seed: "42" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 4,
  });
});

test("component ranges: 11-digit runs are RANGE without conversion", () => {
  assert.deepEqual(errorOf({ notation: "10000000000d6", seed: "42" }), {
    code: "RANGE",
    field: "notation",
    row: null,
    component: "count",
  });
  assert.deepEqual(errorOf({ notation: "2d10000000000", seed: "42" }), {
    code: "RANGE",
    field: "notation",
    row: null,
    component: "sides",
  });
  assert.deepEqual(errorOf({ notation: "2d6+10000000000", seed: "42" }), {
    code: "RANGE",
    field: "notation",
    row: null,
    component: "modifier",
  });
  // Count is checked before sides before modifier.
  assert.deepEqual(errorOf({ notation: "0d1", seed: "42" }), {
    code: "RANGE",
    field: "notation",
    row: null,
    component: "count",
  });
  assert.deepEqual(errorOf({ notation: "2d6-10001", seed: "42" }), {
    code: "RANGE",
    field: "notation",
    row: null,
    component: "modifier",
  });
});

test("capacity: 33-unit notation and 11-unit seed are INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ notation: "123456789012345678901234567890123", seed: "42" }), {
    code: "INPUT_LIMIT",
    field: "notation",
    row: null,
  });
  assert.deepEqual(errorOf({ notation: "2d6", seed: "12345678901" }), {
    code: "INPUT_LIMIT",
    field: "seed",
    row: null,
  });
});

test("seed grammar: leading zero, sign, space, decimal, exponent are INTEGER_FORMAT", () => {
  for (const seed of ["00", "01", "+42", "42 ", "4.2", "1e3", "0x2a"]) {
    assert.deepEqual(errorOf({ notation: "2d6", seed }), {
      code: "INTEGER_FORMAT",
      field: "seed",
      row: null,
    });
  }
});

test("unpaired surrogates are UNICODE, per field", () => {
  assert.deepEqual(errorOf({ notation: "2d6\uD800", seed: "42" }), {
    code: "UNICODE",
    field: "notation",
    row: null,
  });
  assert.deepEqual(errorOf({ notation: "2d6", seed: "\uD800" }), {
    code: "UNICODE",
    field: "seed",
    row: null,
  });
});

test("validation order: notation is checked before seed", () => {
  assert.deepEqual(errorOf({ notation: "", seed: "" }), {
    code: "EMPTY",
    field: "notation",
    row: null,
  });
  assert.deepEqual(errorOf({ notation: "2d", seed: "042" }), {
    code: "NOTATION",
    field: "notation",
    row: null,
    position: 2,
  });
});

test("schema: null, array, string, missing, extra, wrong-type, accessor, symbol", () => {
  for (const input of [
    null,
    [],
    "2d6",
    {},
    { notation: "2d6" },
    { notation: "2d6", seed: "42", extra: 1 },
    { notation: 42, seed: "42" },
    { notation: "2d6", seed: 42 },
  ]) {
    assert.deepEqual(run(input), {
      ok: false,
      error: { code: "SCHEMA", field: null, row: null },
    });
  }
  const accessor = {};
  Object.defineProperty(accessor, "notation", { enumerable: true, get: () => "2d6" });
  Object.defineProperty(accessor, "seed", { enumerable: true, value: "42" });
  assert.deepEqual(run(accessor), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  const symbolled = { notation: "2d6", seed: "42", [Symbol("x")]: 1 };
  assert.deepEqual(run(symbolled), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
});
